-- 2026-05-16 운영 서버 DB 의 표 구조(데이터 없음). 저장 계층 재설계 R0 마이그레이션 견본.
-- 생성: sqlite3 <사본> .schema (개인 데이터 미포함)
CREATE TABLE admin_users (
	username VARCHAR NOT NULL, 
	password_hash VARCHAR NOT NULL, 
	salt VARCHAR NOT NULL, 
	PRIMARY KEY (username)
);
CREATE TABLE api_keys (
	"key" VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	created_at VARCHAR NOT NULL, 
	PRIMARY KEY ("key")
);
CREATE TABLE mysafety_watchlist (
	"신고번호" VARCHAR NOT NULL, 
	PRIMARY KEY ("신고번호")
);
CREATE TABLE mysafety_sync_meta (
	"key" VARCHAR NOT NULL, 
	value VARCHAR NOT NULL, 
	PRIMARY KEY ("key")
);
CREATE TABLE mysafety (
	"ID" VARCHAR NOT NULL, 
	"상태" VARCHAR, 
	"신고번호" VARCHAR, 
	"신고명" VARCHAR, 
	"신고일" VARCHAR, 
	"만족도조사여부" VARCHAR, 
	"별점" INTEGER, 
	"별점사유" VARCHAR, 
	"감시목록" VARCHAR, 
	PRIMARY KEY ("ID")
);
CREATE TABLE mysafety_duplicate_group (
	group_id VARCHAR NOT NULL, 
	fingerprint VARCHAR NOT NULL, 
	match_type VARCHAR NOT NULL, 
	status VARCHAR NOT NULL, 
	representative_mode VARCHAR NOT NULL, 
	representative_id VARCHAR, 
	member_count INTEGER NOT NULL, 
	apply_globally INTEGER NOT NULL, 
	note VARCHAR, 
	created_at INTEGER, 
	updated_at INTEGER, 
	PRIMARY KEY (group_id)
);
CREATE TABLE mysafety_duplicate_member (
	group_id VARCHAR NOT NULL, 
	report_id VARCHAR NOT NULL, 
	report_number VARCHAR NOT NULL, 
	category VARCHAR NOT NULL, 
	is_representative INTEGER NOT NULL, 
	priority_score INTEGER NOT NULL, 
	raw_match INTEGER NOT NULL, 
	field_match INTEGER NOT NULL, 
	created_at INTEGER, 
	updated_at INTEGER, 
	PRIMARY KEY (group_id, report_id)
);
CREATE TABLE mysafety_entry_value (
	"ID" VARCHAR NOT NULL, 
	entry_value VARCHAR NOT NULL, 
	PRIMARY KEY ("ID")
);
CREATE TABLE mysafety_raw_content (
	"ID" VARCHAR NOT NULL, 
	raw_content VARCHAR NOT NULL, 
	raw_type VARCHAR NOT NULL, 
	saved_at INTEGER, 
	PRIMARY KEY ("ID")
);
CREATE TABLE mysafetydetail_other (
	"ID" VARCHAR NOT NULL, 
	"처리상태" VARCHAR, 
	"차량번호" VARCHAR, 
	"위반법규" VARCHAR, 
	"범칙금_과태료" VARCHAR, 
	"벌점" VARCHAR, 
	"처리기관" VARCHAR, 
	"담당자" VARCHAR, 
	"답변일" VARCHAR, 
	"발생일자" VARCHAR, 
	"발생시각" VARCHAR, 
	"위반장소" VARCHAR, 
	"종결여부" VARCHAR, 
	"신고내용" VARCHAR, 
	"처리내용" VARCHAR, 
	"지도" VARCHAR, 
	"첨부사진" VARCHAR, 
	"첨부파일" VARCHAR, 
	synced_at INTEGER, 
	"보완횟수" INTEGER, 
	"보완_미응답" VARCHAR, 
	"보완_요청자" VARCHAR, 
	"보완_요청일시" VARCHAR, 
	"보완_완료일시" VARCHAR, 
	"보완_요청_내용" VARCHAR, 
	"보완_신고자_의견" VARCHAR, 
	PRIMARY KEY ("ID")
);
